/*
 * channel.c - Substitutable slot-capacity function.
 *
 * Without --trace, use a fixed value (--prbs). With --trace, read a CSV
 * generated by channel/channel_model.py in "slot,prbs" format with a header.
 * The trace is reused in a loop if the simulation is longer than the trace.
 */
#include <stdio.h>
#include <stdlib.h>

#include "sim.h"

int channel_load_trace(sim_t *s, const char *path) {
    FILE *f = fopen(path, "r");
    if (!f) return -1;

    int cap = 1024, n = 0;
    int *v = malloc(cap * sizeof *v);
    char line[128];
    fgets(line, sizeof line, f); /* header */
    while (fgets(line, sizeof line, f)) {
        int slot, prbs;
        if (sscanf(line, "%d,%d", &slot, &prbs) != 2) continue;
        if (n == cap) v = realloc(v, (cap *= 2) * sizeof *v);
        v[n++] = prbs;
    }
    fclose(f);
    if (n == 0) {
        free(v);
        return -1;
    }
    s->trace = v;
    s->trace_len = n;
    return 0;
}

int channel_slot_prbs(const sim_t *s, long slot) {
    if (s->trace) return s->trace[slot % s->trace_len];
    return s->cfg.prbs_per_slot;
}
